<template><WorkspaceLayout role="ADMIN"><p class="eyebrow">服务运营</p><h1 class="page-title">把每一步安排妥当。</h1><p v-if="error" class="form-error" role="alert">{{ error }}</p><el-tabs v-model="tab" class="tabs"><el-tab-pane label="订单与派单" name="orders"><div class="surface panel"><div class="panel-head"><h2>订单列表</h2><button class="text-button" @click="loadOrders">刷新</button></div><div v-for="order in orders" :key="order.id" class="row"><div><span class="eyebrow">#{{ order.id }} · {{ order.elder_name }}</span><h3>{{ order.item_name_snapshot }}</h3><p class="muted">{{ formatTime(order.start_at) }} · {{ order.street_name_snapshot }}</p></div><div class="row-end"><button class="text-button" @click="openOrderDetail(order.id)">查看详情</button><strong>{{ statusName(order.status) }}</strong><button v-if="['WAITING_ASSIGNMENT','WAITING_ACCEPTANCE','WAITING_SERVICE'].includes(order.status)" class="primary" @click="openAssign(order)">{{ order.status==='WAITING_ASSIGNMENT'?'人工派单':'普通改派' }}</button><button v-if="order.status==='IN_SERVICE'" class="text-button" @click="interruptOrder(order.id)">异常中断</button><button v-if="['COMPLETED','ABNORMAL_CLOSED'].includes(order.status)" class="text-button" @click="openSettlement(order.id)">结算</button></div></div><div v-if="!orders.length && !error" class="empty">暂无订单。</div></div></el-tab-pane>
<el-tab-pane label="服务目录" name="catalog"><div class="surface panel"><div class="panel-head"><h2>服务项目</h2><button class="primary" @click="openCreateItem">新增项目</button></div><div v-for="item in items" :key="item.id" class="row"><div><span class="eyebrow">{{ categoryName(item.category) }}</span><h3>{{ item.name }}</h3><p class="muted">¥{{ item.unit_price }} · {{ item.pricing_model==='HOURLY'?'按小时':'固定价' }}</p></div><div class="row-end"><span>{{ item.active?'已上架':'未上架' }}</span><button class="text-button" @click="openEditItem(item)">编辑</button><button class="text-button" @click="openTags(item)">需求标签</button><button class="text-button" @click="openCoverage(item)">覆盖街道</button><button v-if="item.active" class="text-button" @click="unpublish(item)">下架</button></div></div><div v-if="!items.length && !error" class="empty">暂无服务项目。</div></div><div class="surface panel"><div class="panel-head"><h2>服务区域</h2><button class="text-button" @click="areaOpen=true">新增区域</button></div><div class="area-list"><span v-for="area in areas" :key="area.id">{{ area.full_name }} · {{ area.level }}</span></div></div></el-tab-pane>
<el-tab-pane label="服务人员" name="workers"><div class="surface panel"><div class="panel-head"><h2>服务人员</h2><button class="primary" @click="workerOpen=true">创建账号</button></div><div v-for="worker in workers" :key="worker.id" class="row"><div><h3>{{ worker.display_name }}</h3><p class="muted">{{ worker.username }} · {{ detailStatus(worker.status) }}</p></div><div class="row-end"><button class="text-button" @click="openWorkerSettings(worker)">能力与排班</button><button v-if="worker.status==='ACTIVE'" class="text-button" @click="changeWorkerState(worker,'pause')">暂停接单</button><button v-if="worker.status==='ACTIVE'" class="text-button" @click="changeWorkerState(worker,'disable')">普通停用</button><button v-if="worker.status==='ACTIVE'" class="text-button" @click="changeWorkerState(worker,'emergency-disable')">紧急停用</button><button v-if="worker.status==='DISABLED'" class="text-button" @click="changeWorkerState(worker,'enable')">恢复账号</button></div></div><div v-if="!workers.length && !error" class="empty">暂无服务人员。</div></div><div class="surface panel"><div class="panel-head"><h2>请假审批</h2><button class="text-button" @click="loadLeaves">刷新</button></div><div v-for="leave in leaves" :key="leave.id" class="row"><div><strong>{{ leave.worker_name }}</strong><p>{{ formatTime(leave.start_at) }} 至 {{ formatTime(leave.end_at) }}</p><p class="muted">{{ leave.reason }}</p></div><div class="row-end"><span>{{ detailStatus(leave.status) }}</span><button v-if="leave.status==='PENDING'" class="primary" @click="decideLeave(leave.id,true)">批准</button><button v-if="leave.status==='PENDING'" class="text-button" @click="decideLeave(leave.id,false)">拒绝</button></div></div><div v-if="!leaves.length" class="empty">暂无请假申请。</div></div></el-tab-pane><el-tab-pane label="异常与争议" name="incidents"><div class="surface panel"><h2>服务中断</h2><div v-for="incident in incidents" :key="incident.id" class="row"><div><strong>订单 #{{ incident.order_id }} · {{ incident.item_name_snapshot }}</strong><p>{{ incident.reason }}</p><p class="muted">{{ incident.elder_name }} · {{ detailStatus(incident.status) }} · 原金额 ¥{{ incident.payable_amount }}</p></div><div class="row-end"><button v-if="incident.status==='OPEN'&&incident.order_status==='INTERRUPTED'" class="primary" @click="openSupplement(incident)">安排补服务</button><button v-if="incident.status==='OPEN'&&incident.order_status==='INTERRUPTED'" class="text-button" @click="openFee(incident)">核实费用</button></div></div><div v-if="!incidents.length" class="empty">暂无服务中断。</div></div><div class="surface panel"><h2>事后争议</h2><div v-for="dispute in disputes" :key="dispute.id" class="row"><div><strong>订单 #{{ dispute.order_id }} · {{ dispute.opened_by_name }}</strong><p>{{ dispute.reason }}</p><p class="muted">{{ detailStatus(dispute.status) }}</p></div><button v-if="dispute.status==='OPEN'" class="text-button" @click="resolveDispute(dispute.id)">记录处理结果</button></div><div v-if="!disputes.length" class="empty">暂无争议。</div></div></el-tab-pane><el-tab-pane label="评价治理" name="reviews"><div class="surface panel"><h2>服务评价</h2><div v-for="review in reviews" :key="review.id" class="row"><div><strong>订单 #{{ review.order_id }} · {{ review.stars }} 星</strong><p>{{ review.content || '无文字评价' }}</p><p class="muted">{{ review.author_name }} · {{ detailStatus(review.visibility) }}</p></div><button v-if="review.visibility==='VISIBLE'" class="text-button" @click="hideReview(review.id)">隐藏评价</button></div><div v-if="!reviews.length" class="empty">暂无评价。</div></div></el-tab-pane><el-tab-pane label="家庭协调" name="family">
<section class="surface panel family-panel"><div class="panel-head"><h2>家庭协调与受控交接</h2><button class="text-button" @click="loadFamilyCoordination">刷新</button></div><h3>本人关联核验</h3><p class="muted">仅在线下核实本人身份后批准，并填写核验依据。</p><div v-for="claim in identityClaims" :key="claim.id" class="row"><div><strong>#{{ claim.id }} · {{ claim.elder_name }} / {{ claim.account_name }}</strong><p class="muted">{{ detailStatus(claim.status) }} · {{ claim.review_note || '待处理' }}</p></div><div class="row-end"><button v-if="claim.status==='PENDING'" class="text-button" @click="decideIdentity(claim.id,'approve')">核验通过</button><button v-if="claim.status==='PENDING'" class="text-button" @click="decideIdentity(claim.id,'reject')">拒绝</button><button v-if="claim.status==='APPROVED'" class="text-button" @click="decideIdentity(claim.id,'revoke')">撤销本人关联</button></div></div><div v-if="!identityClaims.length" class="empty">暂无本人关联申请。</div><h3>家庭关联争议</h3><div v-for="dispute in familyDisputes" :key="dispute.id" class="row"><div><strong>#{{ dispute.id }} · {{ dispute.elder_name }} / {{ dispute.reporter_name }}</strong><p>{{ dispute.reason }}</p><p class="muted">{{ detailStatus(dispute.status) }} · {{ dispute.resolution || '待协调' }}</p></div><button v-if="dispute.status==='OPEN'" class="text-button" @click="resolveFamilyDispute(dispute.id)">记录协调结果</button></div><div v-if="!familyDisputes.length" class="empty">暂无家庭关联争议。</div><h3>指定订单操作交接</h3><p class="muted">仅创建人已失去该操作权限时可交接；接收人仍需当前有效家庭授权。所有交接均保留原因与历史。</p><div class="handover-form"><el-input-number v-model="handoverForm.orderId" :min="1" placeholder="订单编号" /><el-select v-model="handoverForm.action" placeholder="选择操作"><el-option v-for="choice in handoverActions" :key="choice.value" :label="choice.label" :value="choice.value" /></el-select><el-input-number v-model="handoverForm.targetAccountId" :min="1" placeholder="接收人账号编号" /><el-input v-model="handoverForm.reason" maxlength="500" placeholder="交接原因" /><button class="primary" :disabled="!handoverForm.orderId||!handoverForm.targetAccountId||!handoverForm.reason.trim()" @click="createHandover">记录交接</button><button class="text-button" :disabled="!handoverForm.orderId" @click="loadHandovers">查看历史</button></div><div v-for="handover in handovers" :key="handover.id" class="row"><div><strong>#{{ handover.id }} · {{ handover.action }} · {{ handover.target_name }}</strong><p>{{ handover.reason }}</p><p class="muted">{{ detailStatus(handover.status) }}</p></div><button v-if="handover.status==='ACTIVE'" class="text-button" @click="revokeHandover(handover.id)">撤销交接</button></div></section>
<section class="surface panel family-panel"><h2>用户账号状态</h2><p class="muted">停用立即拒绝旧会话；未完成订单由管理员协调交接。</p><div v-for="user in userAccounts" :key="user.id" class="row"><div><strong>#{{ user.id }} · {{ user.display_name }}</strong><p class="muted">{{ user.email }} · {{ detailStatus(user.status) }}</p></div><button v-if="user.status==='ACTIVE'" class="text-button" @click="changeUserStatus(user,'disable')">停用</button><button v-if="user.status==='DISABLED'" class="text-button" @click="changeUserStatus(user,'enable')">恢复</button></div><div v-if="!userAccounts.length" class="empty">暂无用户账号。</div></section></el-tab-pane></el-tabs>
<el-dialog v-model="orderDetailOpen" title="订单详情与处理历史" width="min(94vw, 760px)"><div v-if="orderDetail" class="order-detail"><h3>{{ orderDetail.order.item_name_snapshot }} · #{{ orderDetail.order.id }}</h3><p>{{ orderDetail.order.elder_name }} · 创建人：{{ orderDetail.order.creator_name }}</p><p>预约：{{ formatTime(orderDetail.order.start_at) }} · {{ orderDetail.order.street_name_snapshot }} {{ orderDetail.order.address_snapshot }}</p><p>状态：{{ statusName(orderDetail.order.status) }} · 应付 ¥{{ orderDetail.order.payable_amount }}</p><p>预约规则：{{ orderDetail.order.rule_snapshot }}</p><h4>派单与履约</h4><p v-for="a in orderDetail.assignments" :key="a.id">派单 #{{ a.id }} · {{ a.worker_name }} · {{ detailStatus(a.status) }} {{ a.rejection_reason || "" }}</p><p v-for="f in orderDetail.fulfillments" :key="f.id">履约 #{{ f.id }} · {{ detailStatus(f.status) }}</p><h4>补服务与异常</h4><p v-for="s in orderDetail.supplements" :key="s.id">补服务 #{{ s.id }} · {{ s.reason }} · {{ detailStatus(s.status) }}</p><p v-for="i in orderDetail.incidents" :key="i.id">中断 #{{ i.id }} · {{ i.reason }} · {{ i.resolution || i.status }}</p><p v-for="fee in orderDetail.feeAdjustments" :key="fee.id">费用 #{{ fee.id }} · ¥{{ fee.original_amount }} → ¥{{ fee.proposed_amount }} · {{ fee.reason }} · {{ detailStatus(fee.status) }}</p><p v-for="d in orderDetail.disputes" :key="d.id">争议 #{{ d.id }} · {{ d.reason }} · {{ d.resolution || d.status }}</p><h4>订单事件</h4><p v-for="(event,index) in orderDetail.events" :key="index">{{ formatTime(event.created_at) }} · {{ actionName(event.action) }} · {{ event.note }}</p></div></el-dialog>
<el-dialog v-model="assignOpen" title="人工派单" width="min(94vw, 520px)"><p>{{ selectedOrder?.item_name_snapshot }} · {{ selectedOrder?.elder_name }}</p><el-select v-model="workerId" placeholder="选择符合资格且时间可用的服务人员" style="width:100%"><el-option v-for="worker in candidates" :key="worker.id" :label="worker.display_name" :value="worker.id" /></el-select><p v-if="!candidates.length" class="muted">当前没有可派人员，请先检查能力、区域、排班与占用。</p><template #footer><button class="primary" :disabled="!workerId||busy" @click="assign">确认派单</button></template></el-dialog>
<el-dialog v-model="workerOpen" title="创建服务人员账号" width="min(94vw, 520px)"><el-form label-position="top"><el-form-item label="登录账号"><el-input v-model="workerForm.username" placeholder="4–32 位小写字母、数字或下划线" /></el-form-item><el-form-item label="姓名"><el-input v-model="workerForm.name" /></el-form-item><el-form-item label="初始密码"><el-input v-model="workerForm.password" type="password" show-password placeholder="至少 6 位，交由人员首次登录后修改" /></el-form-item><el-form-item label="邮箱（选填）"><el-input v-model="workerForm.email" type="email" /></el-form-item></el-form><template #footer><button class="primary" :disabled="busy" @click="createWorker">创建</button></template></el-dialog>
<el-dialog v-model="workerSettingsOpen" :title="`${selectedWorker?.display_name || ''} · 能力与排班`" width="min(94vw, 640px)"><h3>可服务项目与街道</h3><div v-for="capability in capabilities" :key="`${capability.item_id}-${capability.street_id}`" class="setting-line">{{ capability.item_name }} · {{ capability.street_name }}</div><div class="form-grid"><el-select v-model="capabilityForm.itemId" placeholder="服务项目"><el-option v-for="item in items.filter(i=>i.active)" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-select v-model="capabilityForm.streetId" placeholder="街道"><el-option v-for="area in areas.filter(a=>a.level==='STREET')" :key="area.id" :label="area.full_name" :value="area.id" /></el-select></div><button class="text-button" @click="addCapability">添加能力</button><h3>每周工作时段</h3><div v-for="schedule in schedules" :key="schedule.id" class="setting-line">周{{ schedule.weekday }} · {{ schedule.start_time }}–{{ schedule.end_time }}</div><div class="form-grid"><el-select v-model="scheduleForm.weekday" placeholder="星期"><el-option v-for="day in 7" :key="day" :label="`周${day}`" :value="day" /></el-select><el-input v-model="scheduleForm.startTime" type="time" /><el-input v-model="scheduleForm.endTime" type="time" /></div><button class="text-button" @click="addSchedule">添加时段</button></el-dialog>
<el-dialog v-model="areaOpen" title="新增服务区域" width="min(94vw, 520px)"><el-form label-position="top"><el-form-item label="层级"><el-select v-model="areaForm.level" style="width:100%"><el-option label="城市" value="CITY" /><el-option label="区县" value="DISTRICT" /><el-option label="街道/乡镇" value="STREET" /></el-select></el-form-item><el-form-item v-if="areaForm.level!=='CITY'" label="上级区域"><el-select v-model="areaForm.parentId" style="width:100%"><el-option v-for="area in validParents" :key="area.id" :label="area.full_name" :value="area.id" /></el-select></el-form-item><el-form-item label="名称"><el-input v-model="areaForm.name" /></el-form-item></el-form><template #footer><button class="primary" :disabled="busy" @click="createArea">保存</button></template></el-dialog>
<el-dialog v-model="itemOpen" :title="editingItemId?'编辑服务项目':'新增服务项目'" width="min(94vw, 650px)"><el-form label-position="top"><div class="form-grid"><el-form-item label="分类"><el-select v-model="itemForm.category"><el-option label="助餐" value="MEAL" /><el-option label="保洁" value="CLEANING" /><el-option label="陪诊" value="ESCORT" /></el-select></el-form-item><el-form-item label="计价"><el-select v-model="itemForm.pricingModel"><el-option label="固定价" value="FIXED" /><el-option label="按小时" value="HOURLY" /></el-select></el-form-item></div><el-form-item label="项目名称"><el-input v-model="itemForm.name" /></el-form-item><el-form-item label="说明"><el-input v-model="itemForm.description" type="textarea" /></el-form-item><div class="form-grid"><el-form-item label="单价（元）"><el-input-number v-model="itemForm.unitPrice" :min="0" :precision="2" /></el-form-item><el-form-item label="提前预约（分钟）"><el-input-number v-model="itemForm.advanceMinutes" :min="0" /></el-form-item><el-form-item label="最短时长（分钟）"><el-input-number v-model="itemForm.minMinutes" :min="1" /></el-form-item><el-form-item label="最长时长（分钟）"><el-input-number v-model="itemForm.maxMinutes" :min="1" /></el-form-item><el-form-item label="可服务开始"><el-input v-model="itemForm.availableFrom" type="time" /></el-form-item><el-form-item label="可服务结束"><el-input v-model="itemForm.availableTo" type="time" /></el-form-item></div><el-form-item label="服务规则"><el-input v-model="itemForm.ruleText" type="textarea" /></el-form-item><p class="muted">{{ editingItemId?'修改只影响后续预约，已有订单保留原快照。':'创建后需设置覆盖街道并发布；未发布项目不会出现在用户目录。' }}</p></el-form><template #footer><button class="primary" :disabled="busy" @click="saveItem">{{ editingItemId?'保存修改':'创建项目' }}</button></template></el-dialog>
<el-dialog v-model="coverageOpen" title="覆盖街道与发布" width="min(94vw, 520px)"><p>{{ coverageItem?.name }}</p><div v-for="area in coverageAreas" :key="area.id" class="setting-line"><span>{{ area.full_name }}</span><button class="text-button" @click="removeCoverage(area.id)">移除</button></div><p v-if="!coverageAreas.length" class="muted">尚未设置覆盖街道。</p><el-select v-model="coverageStreetId" placeholder="选择覆盖街道" style="width:100%"><el-option v-for="area in areas.filter(a=>a.level==='STREET')" :key="area.id" :label="area.full_name" :value="area.id" /></el-select><p class="muted">已上架项目须保留至少一个覆盖街道；如需移除最后一个，请先下架。</p><template #footer><button class="text-button" :disabled="!coverageStreetId||busy" @click="addCoverage">添加覆盖</button><button class="primary" :disabled="busy" @click="publish">发布项目</button></template></el-dialog>
<el-dialog v-model="tagsOpen" title="服务需求标签" width="min(94vw, 520px)"><p>{{ tagsItem?.name }}</p><div class="area-list"><span v-for="tag in itemTags" :key="tag">{{ tag }} <button class="remove-tag" @click="removeItemTag(tag)">×</button></span></div><div class="form-grid"><el-input v-model="newItemTag" maxlength="60" placeholder="输入标签" /><button class="primary" @click="addItemTag">添加标签</button></div></el-dialog>
<el-dialog v-model="settlementOpen" title="订单结算" width="min(94vw, 560px)"><div v-if="settlement"><p>应付金额：¥{{ settlement.settlement.amount }}</p><p>状态：{{ detailStatus(settlement.settlement.status) }} · 方式：{{ settlement.settlement.method ? detailStatus(settlement.settlement.method) : '未选择' }}</p><p v-for="attempt in settlement.attempts" :key="attempt.attempt_ref" class="muted">{{ attempt.attempt_ref }} · {{ detailStatus(attempt.remote_status) }}</p><p class="muted">存在未登记、处理中或尚未终结的模拟交易时，不能登记线下结算。</p></div><template #footer><button v-if="settlement?.settlement.status==='PROCESSING'" class="text-button" @click="syncSettlement">查询模拟交易</button><button v-if="settlement && ['WAITING_METHOD','FAILED'].includes(settlement.settlement.status)" class="primary" :disabled="busy" @click="offline">登记线下结算</button></template></el-dialog>
<el-dialog v-model="feeOpen" title="核实中断订单费用" width="min(94vw, 520px)"><p>订单 #{{ selectedIncident?.order_id }} · 原金额 ¥{{ selectedIncident?.payable_amount }}</p><el-form label-position="top"><el-form-item label="建议金额（元）"><el-input-number v-model="feeForm.amount" :min="0" :precision="2" /></el-form-item><el-form-item label="核实原因"><el-input v-model="feeForm.reason" type="textarea" maxlength="500" /></el-form-item></el-form><p class="muted">有权用户确认后才会结案并使金额生效。</p><template #footer><button class="primary" @click="proposeFee">提交提案</button></template></el-dialog>
<el-dialog v-model="supplementOpen" title="安排补服务" width="min(94vw, 520px)"><p>订单 #{{ selectedIncident?.order_id }} · 原服务记录与中断历史会保留。</p><el-form label-position="top"><el-form-item label="补服务开始时间"><el-input v-model="supplementForm.startAt" type="datetime-local" /></el-form-item><el-form-item label="协调说明"><el-input v-model="supplementForm.reason" type="textarea" maxlength="500" /></el-form-item></el-form><p class="muted">服务时长沿用原订单，仍需重新人工派单和人员接单。</p><template #footer><button class="primary" @click="scheduleSupplement">确认安排</button></template></el-dialog>
</WorkspaceLayout></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import WorkspaceLayout from '../../layouts/WorkspaceLayout.vue'
import { api } from '../../api/client'
type Order={id:number;elder_name:string;item_name_snapshot:string;start_at:string;street_name_snapshot:string;status:string}
type AdminOrderDetail={order:Order & {creator_name:string;address_snapshot:string;rule_snapshot:string;payable_amount:number};events:{action:string;note:string;created_at:string}[];assignments:{id:number;worker_name:string;status:string;rejection_reason:string|null}[];fulfillments:{id:number;status:string;started_at:string|null;submitted_at:string|null;confirmed_at:string|null}[];supplements:{id:number;reason:string;status:string;start_at:string}[];incidents:{id:number;reason:string;status:string;resolution:string|null}[];feeAdjustments:{id:number;original_amount:number;proposed_amount:number;reason:string;status:string}[];disputes:{id:number;reason:string;status:string;resolution:string|null}[]}
type Worker={id:number;username:string;display_name:string;email:string|null;status:string}
type Area={id:number;level:string;name:string;full_name:string}
type Item={id:number;category:string;name:string;description:string;unit_price:number;pricing_model:string;min_minutes:number;max_minutes:number;available_from:string;available_to:string;advance_minutes:number;rule_text:string;active:boolean}
const tab=ref('orders'),orders=ref<Order[]>([]),workers=ref<Worker[]>([]),areas=ref<Area[]>([]),items=ref<Item[]>([]),candidates=ref<Worker[]>([]),error=ref(''),busy=ref(false)
const assignOpen=ref(false),workerOpen=ref(false),areaOpen=ref(false),itemOpen=ref(false),coverageOpen=ref(false),selectedOrder=ref<Order|null>(null),workerId=ref<number>(),coverageItem=ref<Item|null>(null),coverageStreetId=ref<number>()
const coverageAreas=ref<{id:number;full_name:string}[]>([])
const orderDetailOpen=ref(false),orderDetail=ref<AdminOrderDetail|null>(null)
const tagsOpen=ref(false),tagsItem=ref<Item|null>(null),itemTags=ref<string[]>([]),newItemTag=ref('')
const workerForm=reactive({username:'',name:'',password:'',email:''}),areaForm=reactive({level:'CITY',parentId:undefined as number|undefined,name:''})
const itemForm=reactive({category:'MEAL',name:'',description:'',pricingModel:'FIXED',unitPrice:0,minMinutes:60,maxMinutes:120,availableFrom:'08:00',availableTo:'18:00',advanceMinutes:120,ruleText:''})
