const incidents=ref<Incident[]>([]),disputes=ref<Dispute[]>([]),feeOpen=ref(false),selectedIncident=ref<Incident|null>(null),feeForm=reactive({amount:0,reason:''})
const supplementOpen=ref(false),supplementForm=reactive({startAt:'',reason:''})
const workerSettingsOpen=ref(false),selectedWorker=ref<Worker|null>(null),capabilities=ref<Capability[]>([]),schedules=ref<Schedule[]>([])
const capabilityForm=reactive({itemId:undefined as number|undefined,streetId:undefined as number|undefined}),scheduleForm=reactive({weekday:1,startTime:'08:00',endTime:'18:00'})
