type FamilyDispute={id:number;elder_name:string;reporter_name:string;reason:string;status:string;resolution:string|null}
type Handover={id:number;action:string;target_name:string;reason:string;status:string}
type UserAccount={id:number;display_name:string;email:string;status:string}
const identityClaims=ref<IdentityClaim[]>([]),familyDisputes=ref<FamilyDispute[]>([]),handovers=ref<Handover[]>([])
const userAccounts=ref<UserAccount[]>([])
const handoverForm=reactive({orderId:undefined as number|undefined,action:'CONFIRM',targetAccountId:undefined as number|undefined,reason:''})
const handoverActions=[{value:'CANCEL',label:'取消订单'},{value:'CONFIRM',label:'确认完成'},{value:'REVIEW',label:'评价'},{value:'FEE_CONFIRM',label:'确认费用调整'},{value:'DISPUTE',label:'发起事后争议'},{value:'PAYMENT',label:'发起模拟结算'}]
const validParents=computed(()=>areas.value.filter(a=>a.level===(areaForm.level==='DISTRICT'?'CITY':'DISTRICT')))
const labels:Record<string,string>={WAITING_ASSIGNMENT:'待派单',WAITING_ACCEPTANCE:'待接单',WAITING_SERVICE:'待服务',IN_SERVICE:'服务中',WAITING_CONFIRMATION:'待确认',COMPLETED:'已完成',CANCELLED:'已取消',INTERRUPTED:'服务中断',ABNORMAL_CLOSED:'异常结案'}
function statusName(value:string){return labels[value]||value}
const detailLabels:Record<string,string>={ACTIVE:'有效',DISABLED:'已停用',PENDING:'待处理',APPROVED:'已同意',REJECTED:'已拒绝',REVOKED:'已撤销',RESOLVED:'已解决',OPEN:'待处理',ACCEPTED:'已接单',REPLACED:'已改派',RELEASED:'已释放',CONFIRMED:'已确认',SUBMITTED:'已提交',IN_PROGRESS:'服务中',PLANNED:'待派单',ASSIGNED:'已派单',VISIBLE:'可见',HIDDEN:'已隐藏',WAITING_METHOD:'待选择方式',PROCESSING:'处理中',SETTLED:'已结算',FAILED:'失败',CANCELLED:'已取消',UNREGISTERED:'未登记',SUCCESS:'成功',SIMULATED:'模拟支付',OFFLINE:'线下登记',WAIVED:'免收费用'}
function detailStatus(value:string){return detailLabels[value]||statusName(value)}
const actionLabels:Record<string,string>={CREATE:'创建预约',ASSIGN:'人工派单',REASSIGN:'普通改派',ACCEPT:'接单',REJECT:'拒单',START:'开始服务',SUBMIT_COMPLETION:'提交完成',CONFIRM:'确认完成',CANCEL:'取消预约',INTERRUPT:'服务中断',PLAN_SUPPLEMENT:'安排补服务',PROPOSE_FEE:'提出费用调整',REJECT_FEE:'拒绝费用调整',APPROVE_FEE:'同意费用调整',OPEN_DISPUTE:'发起争议'}
function actionName(value:string){return actionLabels[value]||value}
function categoryName(value:string){return ({MEAL:'助餐',CLEANING:'保洁',ESCORT:'陪诊'} as Record<string,string>)[value]||value}
function formatTime(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false})}
async function loadOrders(){try{orders.value=await api<Order[]>('/admin/orders');error.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'订单加载失败'}}
async function openOrderDetail(id:number){try{orderDetail.value=await api<AdminOrderDetail>(`/admin/orders/${id}`);orderDetailOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'订单详情加载失败')}}
async function loadAll(){await loadOrders();try{[workers.value,areas.value,items.value,leaves.value,reviews.value,incidents.value,disputes.value]=await Promise.all([api<Worker[]>('/admin/workers'),api<Area[]>('/catalog/areas'),api<Item[]>('/catalog/admin/items'),api<Leave[]>('/admin/leaves'),api<Review[]>('/admin/reviews'),api<Incident[]>('/admin/incidents'),api<Dispute[]>('/admin/disputes')]);await loadFamilyCoordination()}catch(reason){error.value=reason instanceof Error?reason.message:'基础数据加载失败'}}
async function loadFamilyCoordination(){try{[identityClaims.value,familyDisputes.value,userAccounts.value]=await Promise.all([api<IdentityClaim[]>('/admin/identity-claims'),api<FamilyDispute[]>('/admin/family-disputes'),api<UserAccount[]>('/admin/users')])}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'家庭协调数据加载失败')}}
async function changeUserStatus(user:UserAccount,action:'disable'|'enable'){try{const result=await ElMessageBox.prompt('请填写账号状态处理原因。停用后，该账号现有会话将在下次请求失效，未完订单需人工协调。',action==='disable'?'停用用户账号':'恢复用户账号',{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/admin/users/${user.id}/${action}`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await loadFamilyCoordination();ElMessage.success('账号状态已更新')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function decideIdentity(id:number,decision:'approve'|'reject'|'revoke'){try{const result=await ElMessageBox.prompt('请填写线下核验依据或处理原因。',decision==='approve'?'核验本人身份':'处理本人关联',{inputValidator:value=>Boolean(value?.trim())||'必须填写依据或原因'});await api(`/admin/identity-claims/${id}/${decision}`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await loadFamilyCoordination();ElMessage.success('本人关联已处理')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function resolveFamilyDispute(id:number){try{const result=await ElMessageBox.prompt('请填写家庭关联争议的协调结果。','处理家庭争议',{inputValidator:value=>Boolean(value?.trim())||'必须填写结果'});await api(`/admin/family-disputes/${id}/resolve`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await loadFamilyCoordination();ElMessage.success('处理结果已记录')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function loadHandovers(){if(!handoverForm.orderId)return;try{handovers.value=await api<Handover[]>(`/admin/orders/${handoverForm.orderId}/handovers`)}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'交接历史加载失败')}}
async function createHandover(){if(!handoverForm.orderId||!handoverForm.targetAccountId||!handoverForm.reason.trim())return;try{await ElMessageBox.confirm('交接仅适用于指定订单和操作，系统执行时仍会检查接收人当前授权。','确认受控交接');await api(`/admin/orders/${handoverForm.orderId}/handovers`,{method:'POST',body:JSON.stringify({action:handoverForm.action,targetAccountId:handoverForm.targetAccountId,reason:handoverForm.reason.trim()})});await loadHandovers();ElMessage.success('交接已记录')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function revokeHandover(id:number){if(!handoverForm.orderId)return;try{await api(`/admin/orders/${handoverForm.orderId}/handovers/${id}/revoke`,{method:'POST'});await loadHandovers();ElMessage.success('交接已撤销')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'撤销失败')}}
async function loadLeaves(){try{leaves.value=await api<Leave[]>('/admin/leaves')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'加载失败')}}
async function decideLeave(id:number,approve:boolean){try{await api(`/admin/leaves/${id}/${approve?'approve':'reject'}`,{method:'POST'});await loadLeaves();ElMessage.success('申请已处理')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'处理失败')}}
async function hideReview(id:number){try{const result=await ElMessageBox.prompt('请输入内容治理原因','隐藏评价',{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/admin/reviews/${id}/hide`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});reviews.value=await api<Review[]>('/admin/reviews');ElMessage.success('评价已隐藏并记录原因')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
function openFee(incident:Incident){selectedIncident.value=incident;feeForm.amount=incident.payable_amount;feeForm.reason='';feeOpen.value=true}
async function proposeFee(){if(!selectedIncident.value||!feeForm.reason.trim()){ElMessage.error('请填写核实原因');return}try{await api(`/orders/${selectedIncident.value.order_id}/fee-adjustments`,{method:'POST',body:JSON.stringify(feeForm)});feeOpen.value=false;ElMessage.success('费用提案已提交，等待有权用户确认')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'提交失败')}}
function openSupplement(incident:Incident){selectedIncident.value=incident;supplementForm.startAt='';supplementForm.reason='';supplementOpen.value=true}
async function scheduleSupplement(){if(!selectedIncident.value||!supplementForm.startAt||!supplementForm.reason.trim()){ElMessage.error('请填写补服务时间和说明');return}try{await api(`/admin/orders/${selectedIncident.value.order_id}/supplements`,{method:'POST',body:JSON.stringify(supplementForm)});supplementOpen.value=false;await loadOrders();incidents.value=await api<Incident[]>('/admin/incidents');ElMessage.success('补服务已安排，等待重新派单')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'安排失败')}}
async function resolveDispute(id:number){try{const result=await ElMessageBox.prompt('请填写协调结果','处理争议',{inputValidator:value=>Boolean(value?.trim())||'必须填写处理结果'});await api(`/admin/disputes/${id}/resolve`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});disputes.value=await api<Dispute[]>('/admin/disputes');ElMessage.success('处理结果已记录')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function interruptOrder(id:number){try{const result=await ElMessageBox.prompt('请说明服务中断原因。此操作会释放当前人员占用并进入异常协调。','管理员中断服务',{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/admin/orders/${id}/interrupt`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await loadOrders();incidents.value=await api<Incident[]>('/admin/incidents');ElMessage.success('中断已登记')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function changeWorkerState(worker:Worker,action:'pause'|'disable'|'emergency-disable'|'enable'){try{const result=await ElMessageBox.prompt('请填写操作原因；紧急停用会立即使账号无法继续访问，现有任务需人工协调。',`${worker.display_name} · 人员状态处理`,{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/admin/workers/${worker.id}/${action}`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});workers.value=await api<Worker[]>('/admin/workers');ElMessage.success('人员状态已更新')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function openAssign(order:Order){selectedOrder.value=order;workerId.value=undefined;try{candidates.value=await api<Worker[]>(`/admin/orders/${order.id}/candidates`);assignOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'候选人员加载失败')}}
async function assign(){if(!selectedOrder.value||!workerId.value)return;busy.value=true;try{await api(`/orders/${selectedOrder.value.id}/assign`,{method:'POST',body:JSON.stringify({workerId:workerId.value})});assignOpen.value=false;await loadOrders();ElMessage.success('派单成功')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'派单失败')}finally{busy.value=false}}
async function createWorker(){const username=workerForm.username.trim().toLowerCase();if(!/^[a-z0-9_]{4,32}$/.test(username)){ElMessage.error('账号须为 4–32 位小写字母、数字或下划线');return}if(!workerForm.name.trim()){ElMessage.error('请填写姓名');return}if(workerForm.password.length<6){ElMessage.error('初始密码至少 6 位');return}busy.value=true;try{await api('/admin/workers',{method:'POST',body:JSON.stringify({username,name:workerForm.name.trim(),password:workerForm.password,email:workerForm.email.trim()})});workerOpen.value=false;workerForm.username='';workerForm.name='';workerForm.password='';workerForm.email='';workers.value=await api<Worker[]>('/admin/workers')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'创建失败')}finally{busy.value=false}}
async function openWorkerSettings(worker:Worker){selectedWorker.value=worker;try{[capabilities.value,schedules.value]=await Promise.all([api<Capability[]>(`/admin/workers/${worker.id}/capabilities`),api<Schedule[]>(`/admin/workers/${worker.id}/schedules`)]);workerSettingsOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'加载失败')}}
async function addCapability(){if(!selectedWorker.value||!capabilityForm.itemId||!capabilityForm.streetId){ElMessage.error('请选择项目和街道');return}try{await api(`/admin/workers/${selectedWorker.value.id}/capabilities`,{method:'POST',body:JSON.stringify(capabilityForm)});await openWorkerSettings(selectedWorker.value);ElMessage.success('能力已添加')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'添加失败')}}
async function addSchedule(){if(!selectedWorker.value)return;try{await api(`/admin/workers/${selectedWorker.value.id}/schedules`,{method:'POST',body:JSON.stringify(scheduleForm)});await openWorkerSettings(selectedWorker.value);ElMessage.success('时段已添加')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'添加失败')}}
async function createArea(){if(!areaForm.name.trim()||(areaForm.level!=='CITY'&&!areaForm.parentId)){ElMessage.error('请填写区域与上级');return}busy.value=true;try{await api('/catalog/admin/areas',{method:'POST',body:JSON.stringify({level:areaForm.level,parentId:areaForm.level==='CITY'?null:areaForm.parentId,name:areaForm.name.trim()})});areaOpen.value=false;areas.value=await api<Area[]>('/catalog/areas');ElMessage.success('区域已创建')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'创建失败')}finally{busy.value=false}}
function openCreateItem(){editingItemId.value=null;Object.assign(itemForm,{category:'MEAL',name:'',description:'',pricingModel:'FIXED',unitPrice:0,minMinutes:60,maxMinutes:120,availableFrom:'08:00',availableTo:'18:00',advanceMinutes:120,ruleText:''});itemOpen.value=true}
function openEditItem(item:Item){editingItemId.value=item.id;Object.assign(itemForm,{category:item.category,name:item.name,description:item.description,pricingModel:item.pricing_model,unitPrice:item.unit_price,minMinutes:item.min_minutes,maxMinutes:item.max_minutes,availableFrom:item.available_from.slice(0,5),availableTo:item.available_to.slice(0,5),advanceMinutes:item.advance_minutes,ruleText:item.rule_text});itemOpen.value=true}
async function saveItem(){if(!itemForm.name.trim()||!itemForm.description.trim()||!itemForm.ruleText.trim()){ElMessage.error('请填写项目说明和规则');return}busy.value=true;try{if(editingItemId.value){await api(`/catalog/admin/items/${editingItemId.value}`,{method:'PUT',body:JSON.stringify(itemForm)});ElMessage.success('项目已更新')}else{const created=await api<{id:number}>('/catalog/admin/items',{method:'POST',body:JSON.stringify(itemForm)});ElMessage.success('项目已创建，请配置覆盖区域');items.value=await api<Item[]>('/catalog/admin/items');const item=items.value.find(row=>row.id===created.id);if(item)openCoverage(item)}itemOpen.value=false;items.value=await api<Item[]>('/catalog/admin/items')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'保存失败')}finally{busy.value=false}}
async function unpublish(item:Item){try{await ElMessageBox.confirm(`确定下架「${item.name}」吗？已有订单仍保留原预约内容。`,'下架服务项目',{type:'warning'});await api(`/catalog/admin/items/${item.id}/unpublish`,{method:'POST'});items.value=await api<Item[]>('/catalog/admin/items');ElMessage.success('项目已下架')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function openCoverage(item:Item){coverageItem.value=item;coverageStreetId.value=undefined;try{coverageAreas.value=await api<{id:number;full_name:string}[]>(`/catalog/admin/items/${item.id}/areas`);coverageOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'覆盖街道加载失败')}}
async function addCoverage(){if(!coverageItem.value||!coverageStreetId.value)return;busy.value=true;try{await api(`/catalog/admin/items/${coverageItem.value.id}/areas/${coverageStreetId.value}`,{method:'POST'});coverageAreas.value=await api<{id:number;full_name:string}[]>(`/catalog/admin/items/${coverageItem.value.id}/areas`);ElMessage.success('覆盖街道已添加')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'设置失败')}finally{busy.value=false}}
async function removeCoverage(streetId:number){if(!coverageItem.value)return;try{await ElMessageBox.confirm('确定移除该覆盖街道吗？历史订单不会改变。','移除覆盖');await api(`/catalog/admin/items/${coverageItem.value.id}/areas/${streetId}`,{method:'DELETE'});coverageAreas.value=await api<{id:number;full_name:string}[]>(`/catalog/admin/items/${coverageItem.value.id}/areas`);ElMessage.success('覆盖已移除')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function publish(){if(!coverageItem.value)return;busy.value=true;try{await api(`/catalog/admin/items/${coverageItem.value.id}/publish`,{method:'POST'});items.value=await api<Item[]>('/catalog/admin/items');coverageOpen.value=false;ElMessage.success('项目已发布')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'发布失败')}finally{busy.value=false}}
async function openTags(item:Item){tagsItem.value=item;try{itemTags.value=await api<string[]>(`/catalog/admin/items/${item.id}/tags`);tagsOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'标签加载失败')}}
async function addItemTag(){if(!tagsItem.value||!newItemTag.value.trim())return;try{await api(`/catalog/admin/items/${tagsItem.value.id}/tags`,{method:'POST',body:JSON.stringify({tag:newItemTag.value.trim()})});itemTags.value=await api<string[]>(`/catalog/admin/items/${tagsItem.value.id}/tags`);newItemTag.value=''}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'添加失败')}}
async function removeItemTag(tag:string){if(!tagsItem.value)return;try{await api(`/catalog/admin/items/${tagsItem.value.id}/tags/${encodeURIComponent(tag)}`,{method:'DELETE'});itemTags.value=await api<string[]>(`/catalog/admin/items/${tagsItem.value.id}/tags`)}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'移除失败')}}
async function openSettlement(id:number){try{settlementOrderId.value=id;settlement.value=await api<Settlement>(`/orders/${id}/settlement`);settlementOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'加载失败')}}
async function syncSettlement(){try{settlement.value=await api<Settlement>(`/orders/${settlementOrderId.value}/settlement/sync`,{method:'POST'});ElMessage.success('状态已同步')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'查询失败')}}
async function offline(){try{await api(`/orders/${settlementOrderId.value}/settlement/offline`,{method:'POST'});await openSettlement(settlementOrderId.value);ElMessage.success('线下结算已登记')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'登记失败')}}
onMounted(loadAll)
</script>
